import java.util.*;

class Solution {
    static int[] pairForBudget(int[] prices, int budget) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int j = 0; j < prices.length; j++) {
            Integer i = seen.get(budget - prices[j]);
            if (i != null) return new int[] {i, j};
            seen.putIfAbsent(prices[j], j);
        }
        return new int[0];
    }
}
